# ----------------------------------------------------------------------
# Chart helper
# ----------------------------------------------------------------------
def create_metric_chart(dataframe, incident_df, title, y_col, unit, line_color):
    fig = go.Figure()

    fig.add_trace(
        go.Scatter(
            x=dataframe["Timestamp"],
            y=dataframe[y_col],
            mode="lines",
            name="Telemetry",
            line=dict(color=line_color, width=2),
        )
    )

    fig.add_trace(
        go.Scatter(
            x=incident_df["Timestamp"],
            y=incident_df[y_col],
            mode="markers",
            name="Anomaly",
            marker=dict(color="#f87171", size=8, symbol="circle"),
        )
    )

    fig.update_layout(
        title=dict(
            text=f"<b>{title}</b>",
            font=dict(size=14, color="#e2e8f0"),
        ),
        xaxis_title="",
        yaxis_title=unit,
        template="plotly_dark",
        height=270,
        margin=dict(l=10, r=10, t=45, b=10),
        paper_bgcolor="#111827",
        plot_bgcolor="#111827",
        font=dict(color="#94a3b8"),
        legend=dict(
            orientation="h",
            yanchor="bottom",
            y=1.01,
            xanchor="right",
            x=1,
        ),
    )

    return fig


