# ----------------------------------------------------------------------
# TAB 4: Historical Trends
# ----------------------------------------------------------------------
with tab_trends:
    st.subheader("Historical Trends")
    st.caption(
        "Rolling averages help identify gradual drift that single-point detection can miss."
    )

    window = max(5, sample_count // 20)
    trend_df = df.copy()

    trend_columns = [
        "CPU_Load_%",
        "Temperature_C",
        "RAM_Usage_%",
        "Network_Latency_ms",
        "Packet_Loss_%",
    ]

    for col in trend_columns:
        trend_df[f"{col}_MA"] = trend_df[col].rolling(
            window=window,
            min_periods=1,
        ).mean()

    trend_metrics = [
        ("CPU_Load_%", "CPU Load", "#3b82f6"),
        ("Temperature_C", "Server Temperature", "#f97316"),
        ("RAM_Usage_%", "RAM Consumption", "#8b5cf6"),
        ("Network_Latency_ms", "Network Latency", "#06b6d4"),
        ("Packet_Loss_%", "Packet Loss", "#22c55e"),
    ]

    def create_trend_chart(col, title, color):
        fig = go.Figure()

        fig.add_trace(
            go.Scatter(
                x=trend_df["Timestamp"],
                y=trend_df[col],
                name="Raw",
                line=dict(color=color, width=1),
                opacity=0.35,
            )
        )

        fig.add_trace(
            go.Scatter(
                x=trend_df["Timestamp"],
                y=trend_df[f"{col}_MA"],
                name=f"{window}-min Moving Avg",
                line=dict(color=color, width=3),
            )
        )

        fig.update_layout(
            title=f"<b>{title}</b>",
            template="plotly_dark",
            height=280,
            margin=dict(l=10, r=10, t=40, b=10),
            paper_bgcolor="#111827",
            plot_bgcolor="#111827",
        )

        return fig

    for i in range(0, len(trend_metrics), 2):
        row_metrics = trend_metrics[i : i + 2]
        cols = st.columns(2)

        for col_widget, (metric_col, metric_title, metric_color) in zip(
            cols, row_metrics
        ):
            with col_widget:
                st.plotly_chart(
                    create_trend_chart(
                        metric_col,
                        metric_title,
                        metric_color,
                    ),
                    use_container_width=True,
                )

    st.markdown('<div class="section-label">Summary Statistics</div>', unsafe_allow_html=True)

    st.dataframe(
        df[trend_columns].describe().round(2),
        use_container_width=True,
    )


